"use client";

import { useActionState, useState } from "react";

const REASONS = [
  "Stok opname",
  "Rusak/kadaluarsa",
  "Hilang/dicuri",
  "Kesalahan input awal",
  "Lainnya",
];

type AdjustStockState = { error: string | null };

export default function AdjustStockForm({
  itemName,
  currentStock,
  unit,
  action,
}: {
  itemName: string;
  currentStock: number;
  unit?: string;
  action: (state: AdjustStockState, formData: FormData) => Promise<AdjustStockState>;
}) {
  const [open, setOpen] = useState(false);
  const [state, formAction, pending] = useActionState(action, { error: null } as AdjustStockState);
  const unitSuffix = unit ? ` ${unit}` : "";

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        className="shrink-0 text-xs font-medium text-zinc-400 hover:text-brand-600 hover:underline"
      >
        Sesuaikan stok
      </button>
    );
  }

  return (
