  const stockRaw = formData.get("stock") as string;

  if (!name) {
    return { error: "Nama bahan wajib diisi." };
  }
  if (!unit) {
    return { error: "Satuan wajib diisi (mis. gr, ml, pcs)." };
  }

  const unitCost = unitCostRaw ? Number(unitCostRaw) : 0;
  if (Number.isNaN(unitCost) || unitCost < 0) {
    return { error: "Harga per satuan harus angka dan tidak boleh negatif." };
  }

  const stock = stockRaw ? Number(stockRaw) : 0;
  if (Number.isNaN(stock) || stock < 0) {
    return { error: "Stok harus angka dan tidak boleh negatif." };
  }

  const supabase = await createClient();
  const { error } = await supabase.from("ingredients").insert({
    business_id: businessId,
    name,
    unit,
    unit_cost: unitCost,
    stock,
  });

  if (error) {
    return { error: error.message };
  }

  await logActivity(
    supabase,
    businessId,
    "produk",
    "sukses",
    `Bahan baku baru: ${name}`,
    `Stok ${stock} ${unit}`,
  );
  revalidatePath(`/business/${businessId}/ingredients`);
  return { error: null };
}

export type AdjustStockState = { error: string | null };

export async function adjustIngredientStock(
  businessId: string,
  ingredientId: string,
  _prevState: AdjustStockState,
  formData: FormData,
): Promise<AdjustStockState> {
  const newStockRaw = formData.get("newStock") as string;
  const reason = (formData.get("reason") as string)?.trim();

  const newStock = Number(newStockRaw);
  if (!newStockRaw || Number.isNaN(newStock) || newStock < 0) {
    return { error: "Stok fisik harus angka dan tidak boleh negatif." };
  }
  if (!reason) {
    return { error: "Alasan penyesuaian wajib diisi." };
  }

  const supabase = await createClient();

  const { data: ingredient } = await supabase
    .from("ingredients")
    .select("id, name, unit, stock")
    .eq("id", ingredientId)
    .eq("business_id", businessId)
    .single();

  if (!ingredient) {
    return { error: "Bahan baku tidak ditemukan." };
  }

  const stockBefore = Number(ingredient.stock);
  const diff = newStock - stockBefore;

  if (diff === 0) {
    return { error: "Stok fisik sama dengan stok sistem, tidak ada yang disesuaikan." };
  }

  const { error: updateError } = await supabase
    .from("ingredients")
    .update({ stock: newStock })
    .eq("id", ingredientId);

  if (updateError) {
    return { error: updateError.message };
  }

  await supabase.from("stock_adjustments").insert({
    business_id: businessId,
    ingredient_id: ingredientId,
    item_name: ingredient.name,
    unit: ingredient.unit,
    stock_before: stockBefore,
    stock_after: newStock,
    diff,
    reason,
  });

  await logActivity(
    supabase,
    businessId,
    "produk",
    "warning",
    `Penyesuaian stok: ${ingredient.name}`,
    `${stockBefore} → ${newStock} ${ingredient.unit} (${diff > 0 ? "+" : ""}${diff}) · ${reason}`,
  );
  revalidatePath(`/business/${businessId}/ingredients`);
  return { error: null };
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

const REASONS = [
  "Stok opname",
  "Rusak/kadaluarsa",
  "Hilang/dicuri",
  "Kesalahan input awal",
  "Lainnya",
];

export default function AdjustStockForm({
  itemName,
  currentStock,
  unit,
  action,
}: {
  itemName: string;
  currentStock: number;
  unit?: string;
  action: (formData: FormData) => Promise<{ error: string | null }>;
}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [newStock, setNewStock] = useState(String(currentStock));
  const [reason, setReason] = useState(REASONS[0]);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const unitSuffix = unit ? ` ${unit}` : "";

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        className="shrink-0 text-xs font-medium text-zinc-400 hover:text-brand-600 hover:underline"
      >
        Sesuaikan stok
      </button>
    );
  }

  async function handleSubmit() {
    setError(null);
    setSubmitting(true);
    const formData = new FormData();
    formData.set("newStock", newStock);
    formData.set("reason", reason);
    const result = await action(formData);
    setSubmitting(false);

    if (result.error) {
      setError(result.error);
      return;
    }

    setOpen(false);
    router.refresh();
  }

  return (
    <div className="mt-2 w-full rounded-xl border border-zinc-200 bg-zinc-50 p-3">
      <p className="text-xs text-zinc-500">
        Sesuaikan stok <span className="font-medium text-zinc-700">{itemName}</span> — stok
        sistem saat ini {currentStock}
        {unitSuffix}.
      </p>
      <div className="mt-2 space-y-2">
        <div>
          <label className="mb-1 block text-xs font-medium text-zinc-600">
            Stok fisik sebenarnya{unitSuffix}
          </label>
          <input
            type="number"
            min="0"
            step="any"
            value={newStock}
            onChange={(e) => setNewStock(e.target.value)}
            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-zinc-600">Alasan</label>
          <select
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          >
            {REASONS.map((r) => (
              <option key={r} value={r}>
                {r}
              </option>
            ))}
          </select>
        </div>

        {error && (
          <p className="rounded-lg bg-red-50 px-2 py-1.5 text-xs text-red-600">{error}</p>
        )}

        <div className="flex gap-2">
          <button
            onClick={handleSubmit}
            disabled={submitting}
            className="flex-1 rounded-lg bg-brand-600 py-2 text-xs font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {submitting ? "Menyimpan…" : "Simpan"}
          </button>
          <button
            type="button"
            onClick={() => {
              setOpen(false);
              setError(null);
            }}
            className="rounded-lg px-3 py-2 text-xs font-medium text-zinc-500 hover:text-zinc-700"
          >
            Batal
          </button>
        </div>
      </div>
    </div>
  );
}

