import SwitchCashierButton from "./switch-cashier-button";

type Product = {
  id: string;
  name: string;
  category: string | null;
  price: number;
  cost: number;
  stock: number;
  emoji: string | null;
};

type CartItem = {
  productId: string;
  name: string;
  price: number;
  qty: number;
  maxStock: number;
  disc: number;
  discType: DiscountType;
};

function itemDiscAmount(item: CartItem) {
  const lineGross = item.price * item.qty;
  return item.discType === "pct"
    ? Math.round((lineGross * item.disc) / 100)
    : Math.min(item.disc * item.qty, lineGross);
}

type SelfOrder = {
  id: string;
  status: "baru" | "diproses";
  createdAt: string;
  tableName: string;
  items: {
    productId: string | null;
    name: string;
    qty: number;
    price: number;
    note: string | null;
  }[];
};

type OpenBill = {
  id: string;
  label: string;
  updated_at: string;
  items: {
    product_id: string;
    name: string;
    price: number;
    qty: number;
    disc: number;
    disc_type: DiscountType;
  }[];
};

const PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];

function formatRupiah(value: number) {
  return `Rp${value.toLocaleString("id-ID")}`;
}

export default function PosScreen({
  businessId,
  businessName,
  cashierId,
  cashierName,
  shiftId,
  products,
  taxRate,
  serviceRate,
  openBills,
  isFnb,
  selfOrders,
}: {
  businessId: string;
  businessName: string;
  cashierId: string;
  cashierName: string;
  shiftId: string;
  products: Product[];
  taxRate: number;
  serviceRate: number;
  openBills: OpenBill[];
  isFnb: boolean;
  selfOrders: SelfOrder[];
}) {
  const router = useRouter();
  const [search, setSearch] = useState("");
  const [cart, setCart] = useState<CartItem[]>([]);
  const [inboxOpen, setInboxOpen] = useState(false);
  const [inboxNotice, setInboxNotice] = useState<string | null>(null);
  const [orderBusyId, setOrderBusyId] = useState<string | null>(null);
  const [editingDiscId, setEditingDiscId] = useState<string | null>(null);
  const [orderDisc, setOrderDisc] = useState(0);
  const [orderDiscType, setOrderDiscType] = useState<DiscountType>("pct");
  const [orderDiscOpen, setOrderDiscOpen] = useState(false);
  const [billsOpen, setBillsOpen] = useState(false);
  const [billBusyId, setBillBusyId] = useState<string | null>(null);

