                {b.business_type === "fnb" && (
                  <>
                    <Link
                      href={`/business/${b.id}/ingredients`}
                      className="text-xs font-medium text-zinc-500 hover:underline"
                    >
                      Bahan Baku
                    </Link>
                    <Link
                      href={`/business/${b.id}/tables`}
                      className="text-xs font-medium text-zinc-500 hover:underline"
                    >
                      Meja & Self-Order
                    </Link>
