import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { addCashier } from "./actions";
import AddCashierForm from "./add-cashier-form";

export default async function CashiersPage({
  params,
}: {
  params: Promise<{ businessId: string }>;
}) {
  const { businessId } = await params;
  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  // Explicit column list — pin_hash must never be requested from the client.
  const { data: cashiers } = await supabase
    .from("cashiers")
    .select("id, name, role, active")
    .eq("business_id", businessId)
    .order("created_at", { ascending: true });

  const boundAddCashier = addCashier.bind(null, businessId);

  return (
    <div className="flex flex-1 flex-col items-center bg-zinc-50 px-4 py-10">
      <div className="w-full max-w-sm">
        <Link href="/dashboard" className="text-xs font-medium text-zinc-500 hover:underline">
          ← Kembali ke dashboard
        </Link>

        <h1 className="mt-3 text-lg font-bold text-zinc-900">Kasir — {business.name}</h1>
        <p className="mt-1 text-sm text-zinc-500">
          Daftar kasir yang bisa masuk ke layar kasir toko ini.
        </p>

        <div className="mt-6 space-y-2">
          {cashiers && cashiers.length > 0 ? (
            cashiers.map((c) => (
              <div
                key={c.id}
                className="flex items-center justify-between rounded-xl border border-zinc-200 bg-white px-4 py-3"
              >
                <div>
                  <p className="text-sm font-medium text-zinc-900">{c.name}</p>
                  <p className="text-xs text-zinc-500">
                    {c.role === "manajer" ? "Manajer" : "Kasir"}
                  </p>
                </div>
                {!c.active && (
                  <span className="rounded-full bg-zinc-100 px-2 py-0.5 text-[10px] font-medium text-zinc-500">
                    Nonaktif
                  </span>
                )}
              </div>
            ))
          ) : (
            <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
              Belum ada kasir. Tambahkan minimal satu supaya bisa mulai jualan.
            </p>
          )}
        </div>

        <div className="mt-6 rounded-2xl border border-zinc-200 bg-white p-5">
          <h2 className="mb-4 text-sm font-semibold text-zinc-900">Tambah Kasir</h2>
          <AddCashierForm action={boundAddCashier} />
        </div>
      </div>
    </div>
  );
}

-- Module 7: cashier PIN handling via RPC, so pin_hash never has to be sent
-- to (or compared on) the client. A 4-6 digit PIN has a tiny keyspace, so
-- even a bcrypt hash of it must never leave the database.

-- Belt-and-suspenders: even if a query forgets to exclude pin_hash, the
-- database itself refuses to return that column to these roles.
revoke select (pin_hash) on public.cashiers from authenticated, anon;

-- Create a cashier with a hashed PIN. Only the owner of the business may
-- call this (checked explicitly, since SECURITY DEFINER bypasses RLS).
create or replace function public.create_cashier(
  p_business_id uuid,
  p_name text,
  p_role text,
  p_pin text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  new_id uuid;
begin
  if not private.owns_business(p_business_id) then
    raise exception 'not authorized';
  end if;

  if p_role not in ('kasir', 'manajer') then
    raise exception 'invalid role';
  end if;

  if p_pin !~ '^[0-9]{4,6}$' then
    raise exception 'PIN harus 4-6 digit angka';
  end if;

  insert into public.cashiers (business_id, name, role, pin_hash)
  values (
    p_business_id,
    p_name,
    p_role,
    extensions.crypt(p_pin, extensions.gen_salt('bf'))
  )
  returning id into new_id;

  return new_id;
end;
$$;

grant execute on function public.create_cashier(uuid, text, text, text) to authenticated;

-- Verify a PIN for a given cashier. Returns the cashier row (without
-- pin_hash) on success, or zero rows on a wrong PIN / inactive cashier /
-- cashier belonging to a business the caller doesn't own.
create or replace function public.verify_cashier_pin(
  p_cashier_id uuid,
  p_pin text
)
returns table (id uuid, business_id uuid, name text, role text)
language plpgsql
security definer
set search_path = ''
as $$
begin
  return query
  select c.id, c.business_id, c.name, c.role
  from public.cashiers c
  where c.id = p_cashier_id
    and c.active
    and c.pin_hash = extensions.crypt(p_pin, c.pin_hash)
    and private.owns_business(c.business_id);
end;
$$;

grant execute on function public.verify_cashier_pin(uuid, text) to authenticated;

"use client";

import { useActionState, useRef, useEffect } from "react";
import type { AddCashierState } from "./actions";

const initialState: AddCashierState = { error: null };

export default function AddCashierForm({
  action,
}: {
  action: (state: AddCashierState, formData: FormData) => Promise<AddCashierState>;
}) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (!pending && !state.error) {
      formRef.current?.reset();
    }
  }, [pending, state.error]);

  return (
    <form ref={formRef} action={formAction} className="space-y-4">
      <div>
        <label htmlFor="name" className="mb-1 block text-xs font-medium text-zinc-600">
          Nama Kasir
        </label>
        <input
          id="name"
          name="name"
          type="text"
          required
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          placeholder="mis. Budi"
        />
      </div>

      <fieldset>
        <legend className="mb-2 block text-xs font-medium text-zinc-600">Peran</legend>
        <div className="flex gap-2">
          <label className="flex flex-1 cursor-pointer items-center justify-center gap-2 rounded-xl border border-zinc-200 py-2.5 text-sm has-[:checked]:border-brand-600 has-[:checked]:bg-brand-50">
            <input type="radio" name="role" value="kasir" defaultChecked required className="accent-brand-600" />
            Kasir
          </label>
          <label className="flex flex-1 cursor-pointer items-center justify-center gap-2 rounded-xl border border-zinc-200 py-2.5 text-sm has-[:checked]:border-brand-600 has-[:checked]:bg-brand-50">
            <input type="radio" name="role" value="manajer" required className="accent-brand-600" />
            Manajer
          </label>
        </div>
      </fieldset>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label htmlFor="pin" className="mb-1 block text-xs font-medium text-zinc-600">
            PIN (4 digit)
          </label>
          <input
            id="pin"
            name="pin"
            type="password"
            inputMode="numeric"
            maxLength={4}
            required
            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-center text-sm tracking-widest focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
            placeholder="••••"
          />
        </div>
        <div>
          <label htmlFor="confirmPin" className="mb-1 block text-xs font-medium text-zinc-600">
            Ulangi PIN
          </label>
          <input
            id="confirmPin"
            name="confirmPin"
            type="password"
            inputMode="numeric"
            maxLength={4}
            required
            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-center text-sm tracking-widest focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
            placeholder="••••"
          />
        </div>
      </div>

      {state.error && (
        <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{state.error}</p>
      )}

      <button
        type="submit"
        disabled={pending}
        className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {pending ? "Menyimpan…" : "Tambah Kasir"}
      </button>
    </form>
  );
}

